// Diagnostic adapter only. Calls the unmodified public OFIQ C++ API.
// Input pixels follow the pinned version's image_io.cpp: RGB in 1.0.3,
// BGR in 1.2.0. The driver proves equality against that version's sample CLI.
#include "ofiq_lib.h"
#include <chrono>
#include <cmath>
#include <ctime>
#include <filesystem>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <sstream>
#include <stdexcept>

namespace fs = std::filesystem;
using Clock = std::chrono::steady_clock;

static std::string jsonString(const std::string& value) {
    std::ostringstream out;
    out << '"';
    for (unsigned char c : value) {
        if (c == '"' || c == '\\') out << '\\' << c;
        else if (c < 32) out << "\\u" << std::hex << std::setw(4)
                            << std::setfill('0') << static_cast<int>(c) << std::dec;
        else out << c;
    }
    out << '"';
    return out.str();
}

static void number(std::ostream& out, double value) {
    if (std::isfinite(value)) out << std::setprecision(17) << value;
    else out << "null";
}

static bool mask(const fs::path& path, const std::shared_ptr<uint8_t[]>& pixels,
                 unsigned width, unsigned height) {
    if (!pixels) return false;
    std::ofstream file(path, std::ios::binary);
    file << "P5\n" << width << ' ' << height << "\n255\n";
    file.write(reinterpret_cast<const char*>(pixels.get()), width * height);
    if (!file) throw std::runtime_error("Cannot write diagnostic mask");
    return true;
}

int main(int argc, char** argv) {
    if (argc != 5) {
        std::cerr << "Usage: native_diagnostic CONFIG_DIR CONFIG_FILE INPUT_TSV OUTPUT_DIR\n";
        return 2;
    }
    fs::path output(argv[4]);
    fs::create_directories(output);
    auto implementation = OFIQ::Interface::getImplementation();
    auto start = Clock::now();
    auto cpuStart = std::clock();
    auto initialized = implementation->initialize(argv[1], argv[2]);
    int major = 0, minor = 0, patch = 0;
    implementation->getVersion(major, minor, patch);
    std::ofstream initialization(output / "initialization.json");
    initialization << "{\"version\":[" << major << ',' << minor << ',' << patch
                   << "],\"returnCode\":" << static_cast<int>(initialized.code)
                   << ",\"info\":" << jsonString(initialized.info)
                   << ",\"wallMilliseconds\":"
                   << std::chrono::duration<double, std::milli>(Clock::now() - start).count()
                   << ",\"cpuMilliseconds\":"
                   << 1000.0 * (std::clock() - cpuStart) / CLOCKS_PER_SEC << "}\n";
    initialization.close();
    if (initialized.code != OFIQ::ReturnCode::Success) return 3;
    std::ifstream input(argv[3]);
    if (!input) return 4;
    std::ofstream records(output / "records.jsonl");
    std::string line;
    unsigned completed = 0, failures = 0;
    while (std::getline(input, line)) {
        if (line.empty()) continue;
        std::istringstream parser(line);
        std::string key, widthText, heightText, rawPath;
        if (!std::getline(parser, key, '\t') || !std::getline(parser, widthText, '\t') ||
            !std::getline(parser, heightText, '\t') || !std::getline(parser, rawPath)) return 5;
        if (key.find_first_not_of("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_-") != std::string::npos)
            return 6;
        unsigned width = std::stoul(widthText), height = std::stoul(heightText);
        if (!width || !height || width > 65535 || height > 65535) return 7;
        fs::path target = output / key;
        fs::create_directories(target);
        OFIQ::Image image;
        image.width = static_cast<uint16_t>(width);
        image.height = static_cast<uint16_t>(height);
        image.depth = 24;
        image.data = std::shared_ptr<uint8_t[]>(new uint8_t[image.size()]);
        std::ifstream pixels(rawPath, std::ios::binary);
        pixels.read(reinterpret_cast<char*>(image.data.get()), image.size());
        if (pixels.gcount() != static_cast<std::streamsize>(image.size()) || pixels.peek() != EOF)
            return 8;
        OFIQ::FaceImageQualityAssessment quality;
        OFIQ::FaceImageQualityPreprocessingResult preprocessing;
        start = Clock::now();
        cpuStart = std::clock();
        auto status = implementation->vectorQualityWithPreprocessingResults(
            image, quality, preprocessing, static_cast<uint32_t>(OFIQ::PreprocessingResultType::All));
        double wallMs = std::chrono::duration<double, std::milli>(Clock::now() - start).count();
        double cpuMs = 1000.0 * (std::clock() - cpuStart) / CLOCKS_PER_SEC;
        records << "{\"key\":" << jsonString(key) << ",\"width\":" << width
                << ",\"height\":" << height << ",\"returnCode\":" << static_cast<int>(status.code)
                << ",\"info\":" << jsonString(status.info) << ",\"wallMilliseconds\":";
        number(records, wallMs);
        records << ",\"cpuMilliseconds\":";
        number(records, cpuMs);
        records << ",\"quality\":[";
        bool first = true;
        for (const auto& [measure, result] : quality.qAssessments) {
            if (!first) records << ',';
            first = false;
            records << "{\"measure\":" << static_cast<int>(measure)
                    << ",\"code\":" << static_cast<int>(result.code) << ",\"rawScore\":";
            number(records, result.rawScore);
            records << ",\"scalar\":";
            number(records, result.scalar);
            records << '}';
        }
        records << "],\"faces\":[";
        first = true;
        for (const auto& box : preprocessing.m_faces) {
            if (!first) records << ',';
            first = false;
            records << "{\"x\":" << box.xleft << ",\"y\":" << box.ytop
                    << ",\"w\":" << box.width << ",\"h\":" << box.height << '}';
        }
        records << "],\"landmarks\":[";
        first = true;
        for (const auto& point : preprocessing.m_landmarks.landmarks) {
            if (!first) records << ',';
            first = false;
            records << '[' << point.x << ',' << point.y << ']';
        }
        records << "],\"masks\":{\"segmentation\":"
                << (mask(target / "segmentation.pgm", preprocessing.m_segmentationMaskPtr, width, height) ? "true" : "false")
                << ",\"unoccludedFace\":"
                << (mask(target / "unoccluded-face.pgm", preprocessing.m_occlusionMaskPtr, width, height) ? "true" : "false")
                << ",\"landmarkedRegion\":"
                << (mask(target / "landmarked-region.pgm", preprocessing.m_landmarkedRegionPtr, width, height) ? "true" : "false")
                << "}}\n";
        records.flush();
        ++completed;
        if (status.code != OFIQ::ReturnCode::Success) ++failures;
        std::cout << "completed=" << completed << " failures=" << failures
                  << " key=" << key << " milliseconds=" << wallMs << std::endl;
    }
    return failures ? 9 : 0;
}

